package dailyassignments;

public class Program_CubesofNumbers {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
        int num=1;
        while(num<=5)
        {
        	int cube=num*num*num;
        	System.out.println(num+" cube is "+cube);
        	num++;
        }
	}

}
